// ═══════════════════════════════════════════════════════════════════════
// SECTION 4: TRANSLATION FUNCTIONS
// ═══════════════════════════════════════════════════════════════════════

export const translateCategoryName = (catName: string, lang: 'id' | 'en'): string => {
  if (lang === 'id' || !catName) return catName || '';
  return CATEGORY_TRANSLATIONS[catName]?.en || catName;
};

export const translateSubcategoryName = (subcatName: string, lang: 'id' | 'en'): string => {
  if (lang === 'id' || !subcatName) return subcatName || '';
  return COMPLETE_SUBCATEGORIES_MAP[subcatName] || SUBCATEGORY_TRANSLATIONS[subcatName]?.en || subcatName;
};

export const translateFrameworkName = (fwName: string, lang: 'id' | 'en'): string => {
  if (lang === 'id' || !fwName) return fwName || '';
  return FRAMEWORK_NAMES_MAP[fwName] || fwName;
};

export const translateFrameworkDescription = (desc: string, lang: 'id' | 'en', fwName?: string): string => {
  if (lang === 'id' || !desc) return desc || '';
  if (fwName && FRAMEWORK_DESCRIPTIONS_MAP[fwName]) return FRAMEWORK_DESCRIPTIONS_MAP[fwName];
  return FRAMEWORK_DESCRIPTIONS_MAP[desc] || desc;
};

export const translateComponentLabel = (label: string, lang: 'id' | 'en'): string => {
  if (lang === 'id' || !label) return label || '';
  return COMPLETE_LABELS_MAP[label] || label;
};

export const translateOption = (option: string, lang: 'id' | 'en' = 'id'): string => {
  if (!option) return '';
  if (lang === 'id') {
    return EN_TO_ID_OPTIONS_MAP[option] || String(option);
  }
  return OPTION_TRANSLATIONS[option] || String(option);
};

export const translateInfo = (info: string, lang: 'id' | 'en'): string => {
  if (!info) return '';
  if (lang === 'id') return info;
  return ALL_INFOS_MAP[info] || info;
};

export const translatePlaceholder = (placeholder: string, lang: 'id' | 'en'): string => {
  if (!placeholder) return '';
  if (lang === 'id') {
    if (EN_TO_ID_PLACES_MAP[placeholder]) return EN_TO_ID_PLACES_MAP[placeholder];
    if (placeholder.startsWith('e.g., ')) {
      const rest = placeholder.substring(6).trim();
      return rest ? `contoh: ${rest}` : 'contoh: Masukkan detail di sini...';
    }
    return placeholder;
  }
  // English mode
  if (ALL_PLACES_MAP[placeholder]) return ALL_PLACES_MAP[placeholder];
  if (placeholder.startsWith('Contoh: ') || placeholder.startsWith('contoh: ')) {
    return `e.g., ${placeholder.substring(8).trim()}`;
  }
  return placeholder;
};

